    if isinstance(tree, jinja2.nodes.Name) and tree.name in variable_names:
        line_no = tree.lineno
        line = raw.split("\n")[line_no - 1]
        pos = line.index(tree.name) + 1
        yield SQLTemplaterError(
            f"Undefined jinja template variable: {tree.name!r}",
            line_no=line_no,
            line_pos=pos,
        )

